    typealias SwiftType = Nucleo

    public static func lift(_ handle: UInt64) throws -> Nucleo {
        return Nucleo(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Nucleo) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Nucleo {
        let handle: UInt64 = try readInt(&buf)
