/**
 * Lo que puede salir mal, tal como lo ve Swift (un `enum` que `throws`).
 *
 * Pocas variantes y con el detalle en texto: Swift decide que ensenar por
 * la variante, y el texto es para el registro.
 */
public 
enum ErrorNucleo: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * Leer o escribir en el disco.
     */
    case Disco(detalle: String
    )
    /**
     * Lo pedido no esta (un chat, un lienzo).
     */
    case NoExiste(que: String
    )
    /**
     * Un `.excalidraw` que no se entiende.
     */
    case Lienzo(detalle: String
    )
    /**
     * La red o el protocolo de sincronizar.
     */
    case Sincro(detalle: String
    )
    /**
     * Un argumento que no vale (un codigo de grupo mal escrito...).
     */
    case Argumento(detalle: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension ErrorNucleo: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeErrorNucleo: FfiConverterRustBuffer {
    typealias SwiftType = ErrorNucleo

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ErrorNucleo {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Disco(
            detalle: try FfiConverterString.read(from: &buf)
            )
        case 2: return .NoExiste(
            que: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Lienzo(
            detalle: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Sincro(
            detalle: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Argumento(
            detalle: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ErrorNucleo, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Disco(detalle):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detalle, into: &buf)
            
        
        case let .NoExiste(que):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(que, into: &buf)
            
        
        case let .Lienzo(detalle):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detalle, into: &buf)
            
        
        case let .Sincro(detalle):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detalle, into: &buf)
            
        
        case let .Argumento(detalle):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detalle, into: &buf)
            
        }
    }
}


